SELECT player,
       RANK() OVER (ORDER BY score DESC) AS rk
FROM scores;

SELECT day, amount,
       SUM(amount) OVER (ORDER BY day) AS running
FROM sales;

SELECT day,
       signups - LAG(signups) OVER (ORDER BY day) AS change
FROM daily;

SELECT day,
       AVG(visits) OVER (ORDER BY day /* frame here */) AS avg7
FROM daily_visits;

WITH RECURSIVE sub AS (
  SELECT id FROM categories WHERE id = 2
  UNION ALL
  SELECT c.id FROM categories c JOIN sub s ON c.parent_id = s.id
)
SELECT id FROM sub;

SELECT c.name
FROM customers c
JOIN orders o ON o.customer_id = c.id;

CREATE INDEX ix_orders_customer
  ON orders (customer_id) INCLUDE (status, total);

SELECT status, total FROM orders WHERE customer_id = 42;

CREATE UNIQUE INDEX ux_users_email_live
  ON users (email)
  WHERE deleted_at IS NULL;

-- T1: move 50 from account 1 to account 2
UPDATE accounts SET balance = balance - 50 WHERE id = 1;
UPDATE accounts SET balance = balance + 50 WHERE id = 2;
-- T2, concurrently: move 20 from account 2 to account 1
UPDATE accounts SET balance = balance - 20 WHERE id = 2;
UPDATE accounts SET balance = balance + 20 WHERE id = 1;

INSERT INTO stock (sku, qty) VALUES ('A1', 3), ('B2', 4)
ON CONFLICT (sku) DO UPDATE SET qty = stock.qty + excluded.qty;

SELECT sku, qty FROM stock ORDER BY sku;

CREATE TABLE order_lines (
  qty        int            NOT NULL,
  unit_price numeric(10,2)  NOT NULL,
  total      numeric(12,2)  GENERATED ALWAYS AS (qty * unit_price) STORED
);

CREATE TABLE promo (
  code     text PRIMARY KEY,
  discount int  CHECK (discount BETWEEN 1 AND 100)
);
